<?php $activePage='teams';require_once __DIR__.'/includes/festival.php';$pageTitle=setting('nav_people').' — '.setting('site_name');require __DIR__.'/includes/header.php';$grouped=[];foreach(cms_records('person') as $person)$grouped[$person['fields']['group']][]=$person; ?>
<section class="page-intro section-pad"><h1><?= e(setting('people_page_line1')) ?><br><span class="serif-word"><?= e(setting('people_page_line2')) ?></span></h1><div class="page-intro-bottom" data-reveal><p><?= cms_escape_lines(setting('people_page_copy')) ?></p></div><?php if(setting('people_notice')): ?><p class="archive-note" data-reveal><?= cms_escape_lines(setting('people_notice')) ?></p><?php endif; ?></section>
<section class="team-section section-pad" aria-label="Anazori organising community"><?php foreach($grouped as $group=>$people): ?><h2><?= e($group) ?></h2><div class="team-grid"><?php foreach($people as $person): $f=$person['fields'];$words=preg_split('/\s+/',$person['title']);$initials=mb_substr($words[0],0,1).(count($words)>1?mb_substr(end($words),0,1):''); ?><article class="person-card"><span class="arcane-frame" aria-hidden="true"><i></i><i></i><i></i><i></i></span><div class="person-photo"><?php if($f['image']): ?><img src="<?= e($f['image']) ?>"<?= az_image_attributes84($f['image'],'(max-width:700px) 45vw, (max-width:1100px) 30vw, 22vw') ?> alt="<?= e($person['title']) ?>" loading="lazy" width="350" height="400"><?php else: ?><div class="person-initials" aria-hidden="true"><?= e($initials) ?></div><?php endif; ?></div><h3><?= e($person['title']) ?></h3><p><?= e($f['role']) ?></p><?php if($f['edition']): ?><p class="person-edition"><?= e($f['edition']) ?></p><?php endif;if($f['description']): ?><p class="person-bio"><?= cms_escape_lines($f['description']) ?></p><?php endif;if($f['link']): ?><a href="<?= e($f['link']) ?>" target="_blank" rel="noopener noreferrer" aria-label="View <?= e($person['title']) ?>'s profile">View profile <?= arrow_icon() ?></a><?php endif; ?></article><?php endforeach; ?></div><?php endforeach; ?><?php if(!$grouped): ?><p class="empty-state">Meet the team soon. Our next chapter is coming together.</p><?php endif; ?></section>
